-- 2026-10-07 헌금 중복 정리 (엑셀 자동입력에서 저장을 두 번 눌러 5/31·6/21 명세가 두 번씩 들어감)
-- 뒤에 저장된 복사본 107건만 지운다(5/31 44건 1,298,000원 · 6/21 63건 2,940,000원). 처음 저장분은 그대로.
-- 홈페이지 재정 ▸ 전표입력 ▸ 엑셀 자동입력 ▸ 「겹쳐 저장된 전표 찾기」로도 같은 일을 할 수 있다.
delete from public.offerings where id in (1012,1013,1014,1015,1016,1017,1018,1019,1020,1021,1022,1023,1024,1025,1026,1027,1028,1029,1030,1031,1032,1033,1034,1035,1036,1037,1038,1039,1040,1041,1042,1043,1044,1045,1046,1047,1048,1049,1050,1051,1052,1053,1054,1055,1056,1057,1058,1059,1060,1061,1062,1063,1064,1065,1066,1067,1068,1069,1070,1071,1072,1073,1074,1075,1076,1077,1078,1079,1080,1081,1082,1083,1084,1085,1086,1087,1088,1089,1090,1091,1092,1093,1094,1095,1096,1097,1098,1099,1100,1101,1102,1103,1104,1105,1106,1107,1108,1109,1110,1111,1112,1113,1114,1115,1116,1117,1118);
-- 확인: 날짜별 건수·합계 (5/31 44건 1298000, 6/21 63건 2940000 이어야 함)
select offer_date, count(*), sum(amount) from public.offerings where offer_date in ('2026-05-31','2026-06-21') group by 1 order by 1;
